class Solution {
public:
    int majorityElement(vector<int>& nums) {
        int n = nums.size();
        for (int x : nums) {
            int cnt = 0;
            for (int y : nums) if (y == x) cnt++;
            if (cnt > n / 2) return x;
        }
        return -1;
    }
};

