code.java:
class Solution {
    public int majorityElement(int[] nums) {
        java.util.HashMap<Integer, Integer> counts = new java.util.HashMap<>();
        int n = nums.length;
        for (int x : nums) {
            int c = counts.getOrDefault(x, 0) + 1;
            counts.put(x, c);
            if (c > n / 2) return x;
        }
        return -1;
    }
}

